PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS seed_versions (kind TEXT PRIMARY KEY, version TEXT NOT NULL, sha256 TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (user_id TEXT PRIMARY KEY, display_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (product_id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents >= 0));
CREATE TABLE IF NOT EXISTS inventory (product_id TEXT PRIMARY KEY REFERENCES products(product_id), available_qty INTEGER NOT NULL CHECK(available_qty >= 0), reserved_qty INTEGER NOT NULL DEFAULT 0 CHECK(reserved_qty >= 0), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders (order_id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(user_id), status TEXT NOT NULL CHECK(status IN ('CREATED','PAID','SHIPPED','DELIVERED','CLOSED','CANCELLED')), paid_at TEXT, delivered_at TEXT, paid_cents INTEGER NOT NULL CHECK(paid_cents >= 0), version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS order_items (order_id TEXT NOT NULL REFERENCES orders(order_id), product_id TEXT NOT NULL REFERENCES products(product_id), quantity INTEGER NOT NULL CHECK(quantity > 0), paid_cents INTEGER NOT NULL, PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS shipments (shipment_id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(order_id), status TEXT NOT NULL, observed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS refunds (refund_id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(order_id), status TEXT NOT NULL, amount_cents INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_full_refund_per_order ON refunds(order_id) WHERE status IN ('SUBMITTED','UNDER_REVIEW','APPROVED');
CREATE TABLE IF NOT EXISTS returns (return_id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(order_id), status TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coupons (coupon_code TEXT PRIMARY KEY, policy_id TEXT NOT NULL, version TEXT NOT NULL, min_spend_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tickets (ticket_id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(user_id), order_id TEXT, status TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (session_id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(user_id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (message_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS summaries (session_id TEXT PRIMARY KEY REFERENCES sessions(session_id), summary_json TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pending_actions (action_id TEXT PRIMARY KEY, user_id TEXT NOT NULL, session_id TEXT NOT NULL, tool_name TEXT NOT NULL, args_json TEXT NOT NULL, args_hash TEXT NOT NULL, source_order_version INTEGER, policy_version TEXT, status TEXT NOT NULL, expires_at TEXT NOT NULL, idempotency_key TEXT, resource_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS action_idempotency ON pending_actions(user_id,idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE TABLE IF NOT EXISTS idempotency_records (user_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, args_hash TEXT NOT NULL, result_json TEXT NOT NULL, PRIMARY KEY(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS traces (trace_id TEXT PRIMARY KEY, user_id TEXT, event_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_versions (knowledge_version TEXT PRIMARY KEY, content_sha256 TEXT NOT NULL, applied_at TEXT NOT NULL);
